// Combined Controller: Mouse for XY, Keyboard for Size/Color
noOutput()
noDrag()
setPortCount(1, 1)
setTitle("interactive.control")

let posX = width / 2
let posY = height / 2
let circleSize = 40
let circleColor = '#4ade80' // Default Green

// --- Keyboard Logic ---
onKeyDown((e) => {
  // Change color based on key
  if (e.key === 'r') circleColor = '#f87171' // Red
  if (e.key === 'b') circleColor = '#60a5fa' // Blue
  if (e.key === 'g') circleColor = '#4ade80' // Green

  // Pulse size on spacebar
  if (e.key === ' ') circleSize = 80

  send({ type: 'keydown', key: e.key, x: posX / width, y: posY / height })
})

onKeyUp((e) => {
  if (e.key === ' ') circleSize = 40
  send({ type: 'keyup', key: e.key })
})

// --- Main Loop ---
function draw() {
  // Background
  ctx.fillStyle = '#111827'
  ctx.fillRect(0, 0, width, height)

  // 1. Update Position via Mouse
  if (mouse.down) {
    posX = mouse.x
    posY = mouse.y
    // Send normalized data to output port
    send([posX / width, posY / height])
  }

  // 2. Draw Decorative Grid
  ctx.strokeStyle = '#1f2937'
  ctx.lineWidth = 1
  for (let i = 0; i < width; i += 40) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, height); ctx.stroke()
    ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(width, i); ctx.stroke()
  }

  // 3. Draw the Interactive Element
  ctx.shadowBlur = 15
  ctx.shadowColor = circleColor
  ctx.fillStyle = circleColor

  ctx.beginPath()
  ctx.arc(posX, posY, circleSize, 0, Math.PI * 2)
  ctx.fill()

  // Reset shadow for next frame
  ctx.shadowBlur = 0

  // 4. UI Instructions
  ctx.fillStyle = '#9ca3af'
  ctx.font = '12px sans-serif'
  ctx.fillText('DRAG: Move | R, G, B: Colors | SPACE: Pulse', 10, 20)

  requestAnimationFrame(draw)
}

draw()

noOutput()
noDrag()
setPortCount(1, 1)
setTitle("virtual.keyboard")

// Keyboard Configuration
const keys = ['a', 'w', 's', 'e', 'd', 'f', 't', 'g', 'y', 'h', 'u', 'j', 'k']
const notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B', 'C2']
const activeKeys = new Set()

// Helper to check if a note is a "sharp" (black key)
const isBlackKey = (note) => note.includes('#')

// --- Input Handling ---
onKeyDown((e) => {
  const key = e.key.toLowerCase()
  if (keys.includes(key) && !activeKeys.has(key)) {
    activeKeys.add(key)
    send({ type: 'noteOn', key: key, note: notes[keys.indexOf(key)] })
  }
})

onKeyUp((e) => {
  const key = e.key.toLowerCase()
  activeKeys.delete(key)
  send({ type: 'noteOff', key: key })
})

function draw() {
  ctx.fillStyle = '#18181b'
  ctx.fillRect(0, 0, width, height)

  const keyWidth = width / 8 // Show 8 white keys (C to C)
  let whiteKeyIndex = 0

  // 1. Draw White Keys First
  notes.forEach((note, i) => {
    if (!isBlackKey(note)) {
      const x = whiteKeyIndex * keyWidth
      const isPressed = activeKeys.has(keys[i]) || (mouse.down && mouse.x > x && mouse.x < x + keyWidth && mouse.y > 0)

      // Visual feedback
      ctx.fillStyle = isPressed ? '#4ade80' : '#ffffff'
      ctx.strokeStyle = '#18181b'
      ctx.lineWidth = 2
      ctx.fillRect(x, 0, keyWidth - 2, height)
      ctx.strokeRect(x, 0, keyWidth - 2, height)

      whiteKeyIndex++
    }
  })

  // 2. Draw Black Keys (Overlays)
  whiteKeyIndex = 0
  notes.forEach((note, i) => {
    if (isBlackKey(note)) {
      const x = (whiteKeyIndex * keyWidth) - (keyWidth / 3)
      const isPressed = activeKeys.has(keys[i])

      ctx.fillStyle = isPressed ? '#22c55e' : '#27272a'
      ctx.fillRect(x, 0, keyWidth * 0.6, height * 0.6)
    } else {
      // Only increment white key count when we pass a white key
      whiteKeyIndex++
    }
  })

  // 3. Labels
  ctx.fillStyle = '#71717a'
  ctx.font = '10px monospace'
  ctx.fillText('Use keys: A W S E D F T G Y H U J K', 10, height - 10)

  requestAnimationFrame(draw)
}

draw()

noOutput()
noDrag()
setPortCount(1, 1)
setTitle("mega.terminal")

let currentInput = "> "
let history = [
  "TERMINAL INITIALIZED",
  "--------------------"
]

// Configuration for "Big" feel
const fontSize = 64; // Doubled size
const lineHeight = 70;
const padding = 30;

onKeyDown((e) => {
  if (e.key === 'Enter') {
    const command = currentInput.slice(2).trim()
    if (command.length > 0) {
      history.push(currentInput)
      history.push(`>> ACK: ${command.toUpperCase()}`)
    }
    currentInput = "> "
    send(command.trim())
  } 
  else if (e.key === 'Backspace') {
    if (currentInput.length > 2) currentInput = currentInput.slice(0, -1)
  } 
  else if (e.key.length === 1) {
    currentInput += e.key
  }

  // Keep history relative to screen height
  const maxHistory = Math.floor((height - 100) / lineHeight)
  if (history.length > maxHistory) history.shift()
})

function draw() {
  // Deep black background
  ctx.fillStyle = '#050505'
  ctx.fillRect(0, 0, width, height)

  // Set up the "Big" Font
  ctx.font = `bold ${fontSize}px monospace`

  // Apply a subtle green glow (Bloom effect)
  ctx.shadowBlur = 8
  ctx.shadowColor = '#4ade80'

  // 1. Draw History (Older lines fade out)
  history.forEach((line, i) => {
    const opacity = (i / history.length).toFixed(2)
    ctx.fillStyle = `rgba(74, 222, 128, ${opacity})`
    ctx.fillText(line, padding, padding + fontSize + (i * lineHeight))
  })

  // 2. Draw Active Input (Brighter)
  const inputY = padding + fontSize + (history.length * lineHeight)
  ctx.fillStyle = '#4ade80'
  ctx.shadowBlur = 15 // Extra glow for active line
  ctx.fillText(currentInput, padding, inputY)

  // 3. Massive Blinking Cursor
  if (Math.floor(Date.now() / 400) % 2 === 0) {
    const textWidth = ctx.measureText(currentInput).width
    ctx.fillRect(padding + textWidth + 5, inputY - (fontSize * 0.8), 15, fontSize)
  }

  // 4. CRT Overlay (Scanlines and Vignette)
  ctx.shadowBlur = 0 // Reset shadow for performance

  // Scanlines
  ctx.fillStyle = 'rgba(0, 0, 0, 0.15)'
  for (let i = 0; i < height; i += 6) {
    ctx.fillRect(0, i, width, 3)
  }

  // Corner Vignette (Darkens edges)
  const grd = ctx.createRadialGradient(width/2, height/2, width/4, width/2, height/2, width)
  grd.addColorStop(0, 'rgba(0,0,0,0)')
  grd.addColorStop(1, 'rgba(0,0,0,0.6)')
  ctx.fillStyle = grd
  ctx.fillRect(0, 0, width, height)

  requestAnimationFrame(draw)
}

draw()
